import { Pinecone } from '@pinecone-database/pinecone';

interface SearchOptions {
  queryVector: number[];
  tenantId: string;
  topK: number;
}

/**
 * Executes a scoped vector search to ensure strict data isolation 
 * between different CRM tenants.
 */
async function getTenantSpecificContext({ queryVector, tenantId, topK }: SearchOptions) {
  const pc = new Pinecone({ apiKey: process.env.PINECONE_API_KEY! });
  const index = pc.Index('real-estate-crm-embeddings');

  // Applying a metadata filter ensures the AI model only processes 
  // context belonging to the authorized tenant.
  const queryResponse = await index.query({
    vector: queryVector,
    topK: topK,
    filter: { tenant_id: { $eq: tenantId } },
    includeMetadata: true
  });

  return queryResponse.matches;
}

import { PresidioEngine } from 'presidio-node'; // Wrapper for Microsoft Presidio

const engine = new PresidioEngine();

async function securePromptInterceptor(input: string): Promise<string> {
  // Define PII categories specific to Real Estate (emails, phone numbers, financial amounts)
  const results = await engine.analyze({
    text: input,
    entities: ['EMAIL_ADDRESS', 'PHONE_NUMBER', 'US_SSN', 'LOCATION'],
    language: 'en'
  });

  // Replace sensitive entities with a localized tag to maintain model context
  let sanitizedText = input;
  results.forEach(entity => {
    const replacement = `[REDACTED_${entity.entityType}]`;
    sanitizedText = sanitizedText.replace(entity.text, replacement);
  });

  return sanitizedText;
}

