import { Request, Response, NextFunction } from 'express';

interface UserIdentity {
  id: string;
  role: 'agent' | 'admin';
  assignedRegions: string[];
}

export const authorizeLeadAccess = (req: Request, res: Response, next: NextFunction) => {
  const user = req.user as UserIdentity;
  const leadRequested = req.body.leadData; // Assume lead data contains 'ownerId' and 'region'

  // Policy: Admins have global access, Agents have access only if they are the owner or region-match
  const isOwner = leadRequested.ownerId === user.id;
  const isRegionalMatch = user.assignedRegions.includes(leadRequested.region);
  const isAdmin = user.role === 'admin';

  if (isAdmin || isOwner || isRegionalMatch) {
    return next();
  }

  return res.status(403).json({ error: 'Access Denied: Insufficient attribute permissions for this lead.' });
};

