class PropertyEmbeddingService {
  private buffer: EmbeddingPayload[] = [];
  private readonly BATCH_SIZE = 50;

  constructor(private readonly repo: VectorStoreRepository) {}

  public async queueForEmbedding(payload: EmbeddingPayload): Promise<void> {
    this.buffer.push(payload);
    if (this.buffer.length >= this.BATCH_SIZE) {
      const batch = this.buffer.splice(0, this.BATCH_SIZE);
      await this.repo.upsertBatch(batch);
    }
  }

  // Refactored to utilize repository abstraction for cleaner testing/swapping
  public async getLeadRecommendations(leadCriteria: number[]): Promise<SearchResult[]> {
    return await this.repo.querySimilar(leadCriteria, 5);
  }
}

import Redis from 'ioredis';

interface RecommendationPayload {
  propertyId: string;
  matchScore: number;
  aiReasoning: string;
}

export class AIRecommendationCacheService {
  private redis: Redis;
  // Stale time: 5 minutes (300s) - Serve cached data but trigger updates in background
  private readonly STALE_TTL_SEC = 300;
  // Hard limit: 1 hour (3600s) - Force synchronous fetch if cache is excessively old
  private readonly MAX_TTL_SEC = 3600;

  constructor(redisClient: Redis) {
    this.redis = redisClient;
  }

  /**
   * Retrieves property recommendations using a Stale-While-Revalidate strategy.
   * Reduces API latency from seconds (AI inference/DB fetch) to milliseconds.
   */
  async getCachedRecommendations(
    leadId: string,
    fetchFreshData: () => Promise<RecommendationPayload[]>
  ): Promise<RecommendationPayload[]> {
    const cacheKey = `crm:ai-recs:${leadId}`;
    const staleKey = `crm:ai-recs-stale:${leadId}`;

    try {
      // Attempt to retrieve cached recommendations and check stale status in parallel
      const [cachedData, isStaleIndicator] = await Promise.all([
        this.redis.get(cacheKey),
        this.redis.get(staleKey),
      ]);

      if (cachedData) {
        const parsedData: RecommendationPayload[] = JSON.parse(cachedData);

        // If the stale indicator key is missing, the cache window has expired.
        // Trigger background revalidation asynchronously without blocking the current response.
        if (!isStaleIndicator) {
          this.revalidateCacheInBackground(cacheKey, staleKey, fetchFreshData).catch((err) =>
            console.error(`Background revalidation failed for lead ${leadId}:`, err)
          );
        }

        return parsedData;
      }
    } catch (error) {
      // Fail-soft: log Redis failure and fall back to synchronous direct computation
      console.warn('Redis read failed, falling back to direct computation:', error);
    }

    // Cache miss, Redis failure, or hard TTL expiration: fetch fresh data synchronously
    const freshData = await fetchFreshData();
    await this.writeToCache(cacheKey, staleKey, freshData).catch((err) =>
      console.error('Failed to write fresh data to Redis:', err)
    );

    return freshData;
  }

  private async revalidateCacheInBackground(
    cacheKey: string,
    staleKey: string,
    fetchFreshData: () => Promise<RecommendationPayload[]>
  ): Promise<void> {
    const freshData = await fetchFreshData();
    await this.writeToCache(cacheKey, staleKey, freshData);
  }

  private async writeToCache(
    cacheKey: string,
    staleKey: string,
    data: RecommendationPayload[]
  ): Promise<void> {
    const serialized = JSON.stringify(data);
    // Use Redis transaction (multi) to write both keys atomically
    await this.redis.multi()
      .set(cacheKey, serialized, 'EX', this.MAX_TTL_SEC)
      .set(staleKey, 'true', 'EX', this.STALE_TTL_SEC)
      .exec();
  }
}

