import { LRUCache } from 'lru-cache';

// Initialize cache with a limit of 500 active race states
const raceResultCache = new LRUCache<string, RaceResult>({
  max: 500,
  ttl: 1000 * 60 * 5, // Cache for 5 minutes
});

async function getRaceResults(raceId: string, computeFn: () => RaceResult): Promise<RaceResult> {
  const cachedResult = raceResultCache.get(raceId);

  if (cachedResult) {
    return cachedResult;
  }

  const freshResult = await computeFn();
  raceResultCache.set(raceId, freshResult);

  return freshResult;
}

