export class AsyncRequestManager {
  private activeControllers: Map<string, AbortController> = new Map();

  /**
   * Executes an asynchronous fetch operation while automatically aborting any 
   * outstanding request associated with the same identifier key.
   */
  async fetchSafe<T>(
    key: string,
    url: string,
    options: RequestInit = {}
  ): Promise<T> {
    // Abort previous active request for this key to prevent race conditions
    if (this.activeControllers.has(key)) {
      this.activeControllers.get(key)?.abort();
      this.activeControllers.delete(key);
    }

    const controller = new AbortController();
    this.activeControllers.set(key, controller);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json() as T;
      return data;
    } catch (error: any) {
      if (error.name === 'AbortError') {
        // Log or handle the cancellation gracefully without crashing the runtime
        console.warn(`Request for key "${key}" was cancelled because a newer request was initiated.`);
      }
      throw error;
    } finally {
      // Clean up the controller reference if this specific request completed
      if (this.activeControllers.get(key) === controller) {
        this.activeControllers.delete(key);
      }
    }
  }
}

