import { webcrypto } from 'node:crypto';

async function encryptData(secretKey: CryptoKey, plainText: string): Promise<string> {
  const iv = webcrypto.getRandomValues(new Uint8Array(12));
  const encoded = new TextEncoder().encode(plainText);

  const encrypted = await webcrypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    secretKey,
    encoded
  );

  // Return a base64 string containing both IV and ciphertext for storage
  const combined = new Uint8Array(iv.length + encrypted.byteLength);
  combined.set(iv);
  combined.set(new Uint8Array(encrypted), iv.length);
  return Buffer.from(combined).toString('base64');
}

async function decryptData(secretKey: CryptoKey, base64Data: string): Promise<string> {
  const data = Buffer.from(base64Data, 'base64');
  const iv = data.slice(0, 12);
  const encrypted = data.slice(12);

  const decrypted = await webcrypto.subtle.decrypt(
    { name: 'AES-GCM', iv },
    secretKey,
    encrypted
  );

  return new TextDecoder().decode(decrypted);
}

