  ttl: 1000 * 60 * 5, // Cache entries for 5 minutes
});

async function getCRMEntity(entityId: string): Promise<any> {
  if (entityCache.has(entityId)) {
    return entityCache.get(entityId);
  }

  // Simulating database fetch
  const entity = await db.collection('crm_entities').findOne({ id: entityId });

  if (entity) {
    entityCache.set(entityId, entity);
  }

  return entity;
}

// Generic Repository Interface
interface IRepository<T> {
  findById(id: string): Promise<T | null>;
  findAll(): Promise<T[]>;
  create(data: Omit<T, 'id'>): Promise<T>;
}

// Implementation example for a 'Contact' entity
export class BaseRepository<T> implements IRepository<T> {
  constructor(private readonly model: any) {}

  async findById(id: string): Promise<T | null> {
    return await this.model.findUnique({ where: { id } });
  }

  async findAll(): Promise<T[]> {
    return await this.model.findMany();
  }

  async create(data: Omit<T, 'id'>): Promise<T> {
    return await this.model.create({ data });
  }
}

